function SettingsApp({prefs,changePrefs,reset,runSetup}:{prefs:Prefs;changePrefs:(p:Partial<Prefs>)=>void;reset:()=>void;runSetup:()=>void}) {
 return <div className="settings-app"><div className="settings-sidebar"><div className="settings-profile"><div className="profile-dot large">{(prefs.username||'G').slice(0,1).toUpperCase()}</div><div><b>{prefs.username||'Guest'}</b><small>Local profile</small></div></div>{[['System','Appearance and desktop'],['Personalization','Color and wallpaper'],['Accessibility','Motion and contrast'],['Storage','Browser data']].map(([h,s])=><div className="settings-nav" key={h}><b>{h}</b><small>{s}</small></div>)}</div><div className="settings-content"><p className="eyebrow">PERSONALIZATION</p><h2>Settings</h2><p>Customize your local desktop experience.</p><section className="setting-card"><h3>Appearance</h3><div className="setting-row"><div><b>Theme</b><small>Change the overall interface</small></div><select value={prefs.theme} onChange={e=>changePrefs({theme:e.target.value as Prefs['theme']})}><option value="dark">Dark</option><option value="light">Light</option><option value="system">System</option></select></div><div className="setting-row"><div><b>Accent color</b><small>Buttons, focus and highlights</small></div><div className="accent-picker">{['#8c94ff','#56c8ec','#50c99b','#f0ae73','#ec84ac','#bd94ff'].map(c=><button key={c} style={{background:c}} className={prefs.accent===c?'chosen':''} onClick={()=>changePrefs({accent:c})} aria-label={'Use accent '+c}/>)}</div></div><div className="setting-row"><div><b>Wallpaper</b><small>Desktop background style</small></div><div className="wallpaper-options">{[['aurora','Aurora'],['dusk','Dusk'],['minimal','Minimal']].map(([v,l])=><button key={v} className={prefs.wallpaper===v?'chosen':''} onClick={()=>changePrefs({wallpaper:v})}><span className={'wallpaper-swatch wallpaper-'+v}/>{l}</button>)}</div></div><div className="setting-row wallpaper-upload-row"><div><b>Custom desktop image</b><small>Choose an image and use it as your wallpaper. It is resized and stored locally.</small></div><div className="wallpaper-upload-controls"><label className="secondary-button upload-button"><Upload size={14}/> Choose image<input type="file" accept="image/*" onChange={e=>{const file=e.target.files?.[0];e.currentTarget.value='';if(!file)return;const url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{const scale=Math.min(1,1920/image.width,1200/image.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');if(ctx){ctx.drawImage(image,0,0,canvas.width,canvas.height);changePrefs({wallpaper:'custom',customWallpaper:canvas.toDataURL('image/jpeg',0.8)});}URL.revokeObjectURL(url);};image.onerror=()=>URL.revokeObjectURL(url);image.src=url;}}/></label>{prefs.customWallpaper&&<button className="secondary-button" onClick={()=>changePrefs({wallpaper:'aurora',customWallpaper:undefined})}>Remove image</button>}</div></div><div className="setting-row"><div><b>Taskbar translucency</b><small>Adjust the floating panel surface</small></div><label className="range-inline"><input type="range" min="45" max="100" value={prefs.transparency} onChange={e=>changePrefs({transparency:+e.target.value})}/>{prefs.transparency}%</label></div></section><section className="setting-card"><h3>Accessibility and profile</h3><div className="setting-row"><div><b>Reduce motion</b><small>Keep transitions subtle</small></div><input type="checkbox" checked={!prefs.motion} onChange={e=>changePrefs({motion:!e.target.checked})}/></div><div className="setting-row"><div><b>Desktop name</b><small>Displayed in the Start menu</small></div><input className="profile-input" maxLength={24} value={prefs.username} onChange={e=>changePrefs({username:e.target.value})}/></div></section><section className="setting-card"><h3>Setup experience</h3><p className="hint">Run the first-time setup wizard again. Your desktop data will remain saved.</p><button className="secondary-button" onClick={runSetup}><RotateCcw size={15}/> Run setup wizard again</button></section><section className="setting-card"><h3>Storage and recovery</h3><p className="hint">Notes, events, spreadsheet content, game scores and simulated files remain in browser storage on this device. Clearing browser site data can remove them.</p><button className="danger-button" onClick={reset}><Trash2 size={15}/> Reset AeroShell data</button></section><p className="hint"><ShieldCheck size={14}/> No account or remote API is required. Simulated Wi-Fi, volume and airplane controls do not alter real system settings.</p></div></div>;
}

